const LICENSE="WorldCook original recipe text; factual dish reference cited";
const DAILY_20261004=[
{id:"cypriot-kleftiko",n:"Ofto Kleftiko (Cypriot Slow-Baked Lamb)",c:"Cyprus",f:"🇨🇾",m:180,x:["lamb","potato","lemon","garlic","onion","olive oil"],s:["Rub the lamb with lemon, garlic, salt, pepper, and olive oil.","Place sliced onion and potato beneath the lamb in a tightly covered baking dish.","Bake slowly until the meat is very tender and the potato has absorbed the juices.","Uncover briefly to brown the surface, then rest the lamb before serving."],co:"#a96b3d",source:"https://www.visitcyprus.com/wp-content/uploads/2026/01/New-Guide-To-Cyprus-Booklet_EN_web.pdf",license:LICENSE,sourceNote:NOTE},
{id:"sheftalia",n:"Sheftalia (Cypriot Herb Meat Sausages)",c:"Cyprus",f:"🇨🇾",m:45,x:["pork","lamb","caul fat","onion","parsley","bread"],s:["Mix minced pork and lamb with finely chopped onion, parsley, soaked bread, salt, and pepper.","Shape the mixture into short oval sausages.","Wrap each piece lightly in rinsed caul fat and chill until firm.","Grill while turning until evenly browned and fully cooked, then serve with lemon."],co:"#8d4c35",source:"https://www.visitcyprus.com/discover-cyprus/food-drink/local-recipes/sheftalies-2/",license:LICENSE,sourceNote:NOTE},
{id:"uruguayan-chivito",n:"Chivito (Uruguayan Steak Sandwich)",c:"Uruguay",f:"🇺🇾",m:25,x:["beef","bread","ham","cheese","egg","tomato"],s:["Pound the beef thin, season it, and sear quickly over high heat.","Toast the split bread and layer it with ham, cheese, and sliced tomato.","Place the hot steak inside and top it with a freshly fried egg.","Close the sandwich and serve immediately while the cheese is soft."],co:"#4c8bb5",source:"https://uruguaynatural.com/es/places/montevideo/",license:LICENSE,sourceNote:NOTE},
{id:"torta-frita",n:"Torta Frita (Uruguayan Fried Flatbread)",c:"Uruguay",f:"🇺🇾",m:35,x:["flour","water","butter","salt","sugar","olive oil"],s:["Combine flour and salt, then work in butter and enough warm water for a soft dough.","Rest the dough, divide it, and flatten each piece into a thin round with a small centre hole.","Fry one or two rounds at a time until puffed and golden on both sides.","Drain well and dust lightly with sugar before serving warm."],co:"#d6aa55",source:"https://uruguaynatural.com/en/farmoretanacountry/",license:LICENSE,sourceNote:NOTE},
{id:"nepali-momo",n:"Momo (Nepali Steamed Meat Dumplings)",c:"Nepal",f:"🇳🇵",m:55,x:["flour","ground beef","onion","garlic","ginger","cabbage"],s:["Knead flour and water into a smooth dough and let it rest.","Mix ground meat with finely chopped onion, garlic, ginger, and cabbage.","Roll small wrappers, add filling, and pinch them closed in pleats.","Steam until the wrappers are glossy and the filling is fully cooked."],co:"#b94646",source:"https://trade.ntb.gov.np/nepal-tourism-board-participates-in-pata-dream-to-travel-festival/",license:LICENSE,sourceNote:NOTE},
{id:"dal-bhat-tarkari",n:"Dal Bhat Tarkari (Nepali Lentils, Rice and Vegetables)",c:"Nepal",f:"🇳🇵",m:45,x:["lentils","rice","tomato","onion","garlic","curry powder"],s:["Cook the rice until tender and keep it covered.","Simmer lentils with water, garlic, and a little turmeric or curry seasoning until soft.","Cook onion and tomato with the remaining seasoning to make a simple vegetable tarkari.","Serve rice, lentil soup, and tarkari side by side so each bite can be mixed to taste."],co:"#d29b39",source:"https://trade.ntb.gov.np/know-nepal/culture/",license:LICENSE,sourceNote:NOTE},
{id:"uzbek-plov",n:"Osh Plov (Uzbek Lamb and Carrot Pilaf)",c:"Uzbekistan",f:"🇺🇿",m:75,x:["rice","lamb","carrot","onion","garlic","cumin"],s:["Brown the lamb in a heavy pot, then soften sliced onion in the rendered fat.","Add carrot strips and cumin and cook until fragrant.","Spread rinsed rice over the meat mixture and add measured hot water without stirring.","Nestle in the garlic, cover, and cook gently until the rice is tender and separate."],co:"#4d8b65",source:"https://uzbekistan.travel/en/c/uzbek-cuisine/",license:LICENSE,sourceNote:NOTE},
{id:"uzbek-samsa",n:"Samsa (Uzbek Tandoor-Style Lamb Pastry)",c:"Uzbekistan",f:"🇺🇿",m:60,x:["flour","lamb","onion","butter","cumin","egg"],s:["Mix flour, water, and salt into a firm dough and rest it.","Combine finely diced lamb and onion with cumin, salt, and pepper.","Roll and fold the dough with butter, then cut and shape round wrappers.","Fill, seal into triangles, brush with egg, and bake until deeply golden."],co:"#c88a42",source:"https://uzbekistan.travel/en/o/uzbek-samsa/",license:LICENSE,sourceNote:NOTE},
{id:"maori-hangi",n:"Hāngī (Māori Earth-Oven Meat and Vegetables)",c:"New Zealand",f:"🇳🇿",m:210,x:["chicken","lamb","potato","pumpkin","cabbage","sweet potato"],s:["Season the chicken and lamb and cut the vegetables into large even pieces.","Arrange meat below the vegetables in a covered steaming basket or tightly sealed roasting dish.","Cook slowly with moist heat until the meat is tender and the root vegetables are soft.","Rest briefly, then serve the meat and vegetables together with their smoky-style juices."],co:"#527e58",source:"https://www.newzealand.com/us/feature/maori-hangi/",license:LICENSE,sourceNote:NOTE},
{id:"maori-boil-up",n:"Māori Boil-Up (Pork, Greens and Root Vegetable Broth)",c:"New Zealand",f:"🇳🇿",m:95,x:["pork","potato","sweet potato","cabbage","spinach","water"],s:["Cover the pork with water and simmer gently, skimming the surface as needed.","Add potato and sweet potato pieces and cook until nearly tender.","Add cabbage and spinach near the end so the greens stay vivid.","Season the broth, portion the pork, and serve everything together in deep bowls."],co:"#4f8068",source:"https://www.newzealand.com/ca/feature/traditional-maori-foods/",license:LICENSE,sourceNote:NOTE}
];
window.EXTRA_RECIPES=(window.EXTRA_RECIPES||[]).concat(DAILY_20261004);
