Object.assign(window.RECIPE_I18N,{
"cypriot-kleftiko":{ko:["오프토 클레프티코(키프로스식 저온 구운 양고기)",["양고기에 레몬, 마늘, 소금, 후추, 올리브유를 문질러 바릅니다.","단단히 덮을 수 있는 용기에 양파와 감자를 깔고 양고기를 올립니다.","고기와 감자가 부드러워질 때까지 낮은 온도에서 오래 굽습니다.","마지막에 뚜껑을 열어 겉면을 갈색으로 굽고 잠시 휴지합니다."]],es:["Ofto kleftiko (cordero chipriota asado lentamente)",["Frota el cordero con limón, ajo, sal, pimienta y aceite.","Pon cebolla y patata bajo la carne en una fuente bien tapada.","Hornea lentamente hasta que carne y patata estén tiernas.","Destapa para dorar y deja reposar antes de servir."]],ja:["オフト・クレフティコ（キプロス風ラムの低温焼き）",["ラムにレモン、にんにく、塩、こしょう、油をすり込みます。","密閉できる器に玉ねぎとじゃがいもを敷き、肉をのせます。","肉といもが柔らかくなるまで低温で長く焼きます。","ふたを外して表面を焼き、少し休ませます。"]],zh:["奥夫托克莱夫蒂科（塞浦路斯慢烤羊肉）",["羊肉抹柠檬、大蒜、盐、胡椒和橄榄油。","密封烤皿底铺洋葱和土豆，放上羊肉。","低温慢烤至肉和土豆软嫩。","揭盖略烤上色，静置后食用。"]]},
"sheftalia":{ko:["셰프탈리아(키프로스식 허브 고기 소시지)",["다진 돼지고기와 양고기에 양파, 파슬리, 불린 빵, 소금, 후추를 섞습니다.","짧은 타원형 소시지로 빚습니다.","씻은 그물지방으로 가볍게 감싸 차갑게 굳힙니다.","돌려가며 속까지 완전히 익고 고르게 노릇해지도록 굽습니다."]],es:["Sheftalia (salchicha chipriota de carne y hierbas)",["Mezcla cerdo y cordero con cebolla, perejil, pan, sal y pimienta.","Forma salchichas ovaladas cortas.","Envuelve ligeramente con redaño limpio y enfría.","Asa girando hasta dorar y cocinar por completo."]],ja:["シェフタリア（キプロス風ハーブ入り肉ソーセージ）",["豚肉とラムに玉ねぎ、パセリ、浸したパン、塩、こしょうを混ぜます。","短い楕円形にまとめます。","洗った網脂で軽く包み、冷やします。","返しながら全体を色よく中まで焼きます。"]],zh:["塞浦路斯香草肉肠",["猪肉和羊肉末拌洋葱、欧芹、泡软面包、盐和胡椒。","捏成短椭圆香肠。","用洗净网油轻轻包裹并冷藏定型。","翻面烧烤至均匀上色并完全熟透。"]]},
"uruguayan-chivito":{ko:["치비토(우루과이식 스테이크 샌드위치)",["쇠고기를 얇게 두드려 간한 뒤 센 불에 빠르게 굽습니다.","빵을 갈라 굽고 햄, 치즈, 토마토를 올립니다.","뜨거운 스테이크와 갓 부친 달걀을 얹습니다.","치즈가 부드러울 때 샌드위치를 닫아 바로 냅니다."]],es:["Chivito (sándwich uruguayo de filete)",["Aplana, sazona y sella la carne a fuego alto.","Tuesta el pan y coloca jamón, queso y tomate.","Añade el filete caliente y un huevo recién frito.","Cierra y sirve mientras el queso está blando."]],ja:["チビート（ウルグアイ風ステーキサンド）",["牛肉を薄くたたき、味をつけて強火で焼きます。","パンを焼き、ハム、チーズ、トマトを重ねます。","熱いステーキと焼きたての卵をのせます。","チーズが柔らかいうちに挟んで出します。"]],zh:["奇维托（乌拉圭牛排三明治）",["牛肉拍薄调味，大火快速煎制。","面包烤香，铺火腿、奶酪和番茄。","放上热牛排和现煎鸡蛋。","趁奶酪柔软时合上立即食用。"]]},
"torta-frita":{ko:["토르타 프리타(우루과이식 튀긴 납작빵)",["밀가루와 소금을 섞고 버터와 따뜻한 물을 넣어 부드럽게 반죽합니다.","반죽을 휴지한 뒤 나눠 얇은 원형으로 펴고 가운데 구멍을 냅니다.","부풀고 양면이 노릇해질 때까지 한두 장씩 튀깁니다.","기름을 충분히 빼고 설탕을 살짝 뿌려 따뜻하게 냅니다."]],es:["Torta frita (pan plano frito uruguayo)",["Mezcla harina y sal y añade mantequilla y agua tibia.","Reposa, divide y aplana en discos con un agujero central.","Fríe hasta inflar y dorar por ambos lados.","Escurre y espolvorea ligeramente con azúcar."]],ja:["トルタ・フリタ（ウルグアイ風揚げ平パン）",["小麦粉と塩にバターと温水を加えてこねます。","休ませて分け、中央に穴のある薄い円形にします。","膨らみ両面が色づくまで揚げます。","油を切り、砂糖を少量ふって温かく出します。"]],zh:["乌拉圭油炸扁面包",["面粉和盐混合，加入黄油与温水揉成软面团。","醒面后分份，擀成中央有小孔的薄圆片。","逐片炸至鼓起、两面金黄。","充分沥油，薄撒糖后趁热食用。"]]},
"nepali-momo":{ko:["모모(네팔식 찐 고기만두)",["밀가루와 물로 매끈한 반죽을 만들어 휴지합니다.","다진 고기에 양파, 마늘, 생강, 양배추를 잘게 썰어 섞습니다.","작은 만두피를 밀어 속을 넣고 주름을 잡아 닫습니다.","피가 윤기 나고 속까지 완전히 익도록 찝니다."]],es:["Momo (empanadillas nepalesas de carne al vapor)",["Amasa harina y agua y deja reposar.","Mezcla carne con cebolla, ajo, jengibre y col.","Estira discos, rellena y cierra con pliegues.","Cuece al vapor hasta que masa y relleno estén hechos."]],ja:["モモ（ネパール風蒸し肉餃子）",["小麦粉と水をこねて休ませます。","ひき肉に玉ねぎ、にんにく、生姜、キャベツを混ぜます。","小さな皮を伸ばし、具を包んでひだを寄せます。","皮につやが出て中まで火が通るまで蒸します。"]],zh:["馍馍（尼泊尔蒸肉饺）",["面粉加水揉光滑并醒面。","肉末拌细切洋葱、大蒜、生姜和卷心菜。","擀小皮，放馅后捏褶封口。","蒸至饺皮透亮、肉馅全熟。"]]},
"dal-bhat-tarkari":{ko:["달 바트 타르카리(네팔식 렌틸콩·밥·채소 한상)",["쌀을 부드럽게 익혀 덮어 둡니다.","렌틸콩을 물, 마늘, 약간의 카레 양념과 부드럽게 끓입니다.","양파와 토마토를 남은 양념과 볶아 간단한 채소 타르카리를 만듭니다.","밥, 렌틸콩 수프, 타르카리를 나란히 담아 취향대로 섞어 먹습니다."]],es:["Dal bhat tarkari (lentejas, arroz y verduras de Nepal)",["Cuece el arroz y mantenlo tapado.","Cuece lentejas con agua, ajo y especias hasta tiernas.","Cocina cebolla y tomate con especias para el tarkari.","Sirve arroz, dal y tarkari juntos para mezclar al gusto."]],ja:["ダル・バート・タルカリ（ネパール風豆スープ・ご飯・野菜）",["米を炊いてふたをしておきます。","レンズ豆を水、にんにく、香辛料と柔らかく煮ます。","玉ねぎとトマトを香辛料で炒め、タルカリを作ります。","ご飯、ダル、タルカリを並べ、好みで混ぜます。"]],zh:["达尔巴特塔卡里（尼泊尔扁豆饭配蔬菜）",["米饭煮熟后加盖保温。","扁豆加水、大蒜和香料煮软。","洋葱和番茄加其余香料炒成蔬菜塔卡里。","米饭、豆汤和塔卡里分放，按口味混合食用。"]]},
"uzbek-plov":{ko:["오시 플로브(우즈베키스탄식 양고기·당근 필라프)",["두꺼운 냄비에서 양고기를 갈색으로 굽고 나온 기름에 양파를 익힙니다.","채 썬 당근과 쿠민을 넣어 향이 날 때까지 볶습니다.","씻은 쌀을 고기 위에 펴고 젓지 않은 채 계량한 뜨거운 물을 붓습니다.","통마늘을 넣고 덮어 쌀알이 부드럽고 고슬해질 때까지 익힙니다."]],es:["Osh plov (pilaf uzbeko de cordero y zanahoria)",["Dora el cordero y ablanda la cebolla en la grasa.","Añade zanahoria y comino.","Extiende arroz lavado y vierte agua caliente sin remover.","Añade ajo, tapa y cuece hasta que el arroz quede tierno y suelto."]],ja:["オシュ・プロフ（ウズベキスタン風ラムとにんじんのピラフ）",["厚手鍋でラムを焼き、その脂で玉ねぎを炒めます。","にんじんとクミンを加えます。","洗った米を広げ、混ぜずに計量した湯を注ぎます。","にんにくを入れてふたをし、米が柔らかくほぐれるまで炊きます。"]],zh:["乌兹别克羊肉胡萝卜抓饭",["厚锅中羊肉煎黄，用油脂炒软洋葱。","加入胡萝卜丝和孜然炒香。","洗净米铺在肉上，勿搅拌，倒入定量热水。","放入整蒜，加盖焖至米粒熟软分明。"]]},
"uzbek-samsa":{ko:["삼사(우즈베키스탄식 탄두르 양고기 페이스트리)",["밀가루, 물, 소금으로 단단한 반죽을 만들어 휴지합니다.","잘게 썬 양고기와 양파에 쿠민, 소금, 후추를 섞습니다.","반죽에 버터를 발라 접고 말아 자른 뒤 둥근 피를 만듭니다.","속을 넣어 삼각형으로 봉하고 달걀물을 발라 진한 금빛이 나도록 굽습니다."]],es:["Samsa (pastel uzbeko de cordero al estilo tandur)",["Haz una masa firme con harina, agua y sal.","Mezcla cordero y cebolla con comino, sal y pimienta.","Pliega la masa con mantequilla y forma discos.","Rellena, sella en triángulos, pinta con huevo y hornea hasta dorar."]],ja:["サムサ（ウズベキスタン風タンドール式ラムパイ）",["小麦粉、水、塩で固めの生地を作り休ませます。","ラムと玉ねぎにクミン、塩、こしょうを混ぜます。","生地にバターを塗って折り、切って丸い皮にします。","包んで三角形に閉じ、卵を塗って濃いきつね色に焼きます。"]],zh:["桑萨（乌兹别克烤炉羊肉酥饼）",["面粉、水和盐揉成较硬面团并醒发。","羊肉和洋葱拌孜然、盐与胡椒。","面团涂黄油折叠卷起，切段擀圆。","包馅封成三角，刷蛋液烤至深金黄。"]]},
"maori-hangi":{ko:["항이(마오리식 땅속화덕 고기·채소요리)",["닭고기와 양고기에 간하고 채소를 큼직하고 고르게 썹니다.","덮개 있는 찜 바구니나 단단히 밀봉한 오븐 용기에 고기 아래, 채소 위 순서로 담습니다.","고기가 부드럽고 뿌리채소가 익을 때까지 습열로 천천히 익힙니다.","잠시 휴지한 뒤 고기와 채소를 훈연풍 육즙과 함께 냅니다."]],es:["Hāngī (carne y verduras maoríes al horno de tierra)",["Sazona carnes y corta las verduras en trozos grandes.","Pon carne debajo y verduras encima en un recipiente sellado.","Cocina lentamente con humedad hasta que todo esté tierno.","Reposa y sirve junto con los jugos de sabor ahumado."]],ja:["ハンギ（マオリ式アースオーブンの肉と野菜）",["鶏肉とラムに味をつけ、野菜を大きく切ります。","密閉容器に肉を下、野菜を上にして並べます。","肉と根菜が柔らかくなるまで湿熱でゆっくり加熱します。","少し休ませ、燻製風の肉汁と一緒に盛ります。"]],zh:["杭伊（毛利地炉肉类蔬菜）",["鸡肉和羊肉调味，蔬菜切成均匀大块。","密封蒸篮或烤皿中肉放下层、蔬菜放上层。","湿热慢烹至肉和根茎蔬菜软嫩。","稍静置，连同烟熏风味肉汁一起上桌。"]]},
"maori-boil-up":{ko:["마오리 보일업(돼지고기·푸른잎·뿌리채소 국물요리)",["돼지고기가 잠기게 물을 붓고 거품을 걷으며 약하게 끓입니다.","감자와 고구마를 넣어 거의 부드러워질 때까지 익힙니다.","마지막에 양배추와 시금치를 넣어 푸른색을 살립니다.","국물 간을 맞추고 돼지고기를 나눠 깊은 그릇에 함께 담습니다."]],es:["Boil-up maorí (caldo de cerdo, hojas y raíces)",["Cubre el cerdo con agua y cuece retirando la espuma.","Añade patata y batata hasta casi tiernas.","Incorpora col y espinaca al final.","Sazona y sirve carne, verduras y caldo en cuencos."]],ja:["マオリ・ボイルアップ（豚肉・青菜・根菜のスープ）",["豚肉を水で覆い、あくを取りながら煮ます。","じゃがいもとさつまいもを加え、ほぼ柔らかくします。","最後にキャベツとほうれん草を加えます。","スープを調え、肉と野菜を深い器に盛ります。"]],zh:["毛利水煮杂烩（猪肉绿叶根菜汤）",["猪肉加水没过，小火煮并撇去浮沫。","加入土豆和红薯煮至近软。","最后加入卷心菜和菠菜保持翠绿。","汤汁调味，猪肉分份，与蔬菜一同装深碗。"]]}
});
